# srs.py -- a Leitner-box scheduler for your question notebook. Standard library only.
from dataclasses import dataclass, replace
from datetime import date, timedelta

INTERVAL_DAYS = {1: 1, 2: 3, 3: 7, 4: 14, 5: 30}   # days until the next review, per box
GRADES = ("missed", "partial", "solid")


@dataclass(frozen=True)
class Card:
    qid: str          # for example "rag-03"
    box: int = 1
    due: date = date(2026, 11, 1)


def review(card: Card, grade: str, today: date) -> Card:
    """missed -> back to box 1; partial -> repeat the same box; solid -> promote one box (max 5)."""
    if grade not in GRADES:
        raise ValueError(f"grade must be one of {GRADES}")
    if grade == "missed":
        box = 1
    elif grade == "partial":
        box = card.box
    else:
        box = min(card.box + 1, 5)
    return replace(card, box=box, due=today + timedelta(days=INTERVAL_DAYS[box]))


def due_today(cards: list[Card], today: date, limit: int = 8) -> list[Card]:
    """Oldest-due first, lowest box first, capped so a drill session stays 20 to 30 minutes."""
    ready = [c for c in cards if c.due <= today]
    return sorted(ready, key=lambda c: (c.due, c.box, c.qid))[:limit]


def test_srs() -> None:
    d = date(2026, 11, 2)
    c = Card("sql-01", box=2, due=d)
    assert review(c, "solid", d) == Card("sql-01", 3, d + timedelta(days=7))
    assert review(c, "partial", d) == Card("sql-01", 2, d + timedelta(days=3))
    assert review(c, "missed", d) == Card("sql-01", 1, d + timedelta(days=1))
    assert review(Card("x", 5, d), "solid", d).box == 5          # capped at the top box
    cards = [Card("a", 3, date(2026, 11, 5)), Card("b", 1, date(2026, 11, 1)), Card("c", 2, date(2026, 11, 1))]
    assert [x.qid for x in due_today(cards, date(2026, 11, 2))] == ["b", "c"]   # a is not due yet
    assert due_today(cards, date(2026, 11, 2), limit=1)[0].qid == "b"
    try:
        review(c, "great", d)
        raise AssertionError("should reject unknown grade")
    except ValueError:
        pass


if __name__ == "__main__":
    test_srs()
    print("srs ok")

"""Read weekly self-scores (CSV: week,domain,score) and print the decision each domain triggers."""
import csv
import io
import sys

CORE_TARGET = 3
PROJECT_TARGET = 4
PROJECT_DOMAIN = "project_defense"


def load(text: str) -> dict[str, list[tuple[int, int]]]:
    data: dict[str, list[tuple[int, int]]] = {}
    for row in csv.DictReader(io.StringIO(text)):
        score = int(row["score"])
        if not 0 <= score <= 5:
            raise ValueError(f"score out of range: {row}")
        data.setdefault(row["domain"], []).append((int(row["week"]), score))
    return {d: sorted(v) for d, v in data.items()}


def decide(history: list[tuple[int, int]], domain: str) -> str:
    scores = [s for _, s in history]
    now = scores[-1]
    target = PROJECT_TARGET if domain == PROJECT_DOMAIN else CORE_TARGET
    stalled = len(scores) >= 3 and max(scores[-3:]) == min(scores[-3:]) and now < target
    if len(scores) >= 2 and now < scores[-2]:
        return "DROPPED: decay. Add a 20-minute closed-book recall to next week, then re-score."
    if stalled:
        return "STALLED 3 weeks below target: keep two focused sessions but change the method (build or explain aloud, not more reading)."
    if now < CORE_TARGET:
        return "BELOW 3: schedule two focused sessions next week; no new unrelated tutorials."
    if now < target:
        return f"BELOW TARGET ({target}): keep building; ship a measurable artifact."
    return "ON TARGET: maintain with one recall session a week."


def report(text: str) -> list[str]:
    return [f"{d:<16} now={h[-1][1]} trend={[s for _, s in h]} -> {decide(h, d)}"
            for d, h in sorted(load(text).items())]


if __name__ == "__main__":
    print("\n".join(report(open(sys.argv[1]).read() if len(sys.argv) > 1 else sys.stdin.read())))

import pytest

from readiness import decide, load, report


def test_below_three_triggers_focused_sessions():
    assert decide([(1, 1), (2, 2)], "rag").startswith("BELOW 3")


def test_drop_beats_everything_else():
    assert decide([(1, 3), (2, 4), (3, 3)], "rag").startswith("DROPPED")


def test_stalled_three_weeks_below_target():
    assert decide([(1, 2), (2, 2), (3, 2)], "system_design").startswith("STALLED")


def test_project_needs_four():
    assert decide([(1, 3), (2, 3)], "project_defense").startswith("BELOW TARGET (4)")
    assert decide([(1, 3), (2, 4)], "project_defense").startswith("ON TARGET")


def test_core_target_three_is_on_target():
    assert decide([(1, 2), (2, 3)], "rag").startswith("ON TARGET")


def test_rejects_bad_score():
    with pytest.raises(ValueError):
        load("week,domain,score\n1,rag,6\n")


def test_report_has_one_line_per_domain():
    text = "week,domain,score\n1,rag,2\n2,rag,3\n1,agents,1\n2,agents,2\n"
    assert len(report(text)) == 2
